def _build_component_06():
    def rounded(numerator, denominator, mode):
        quotient, remainder = divmod(numerator, denominator)
        if mode == "half_up" and 2 * remainder >= denominator:
            quotient += 1
        return quotient

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        chosen = {}
        for position, event in enumerate(data["events"]):
            sequence = event.get("sequence", 0)
            if sequence > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            key = (sequence, event.get("revision", 0), position)
            if event_id not in chosen or key > chosen[event_id][0]:
                chosen[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in chosen.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000, mode)
            tax = rounded(net * event.get("tax_bp", 0), 10000, mode)
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        roots = data["roots"]

        domains = {}
        for name in names:
            versions = sorted(
                (row["version"] for row in packages[name]
                 if row["version"] not in blocked.get(name, []) and
                 (name not in pins or row["version"] == pins[name])),
                reverse=True,
            )
            domains[name] = versions + [-1]

        assignment = {}

        def feasible():
            for name, bounds in roots.items():
                version = assignment.get(name, -1)
                if version < bounds[0] or version > bounds[1]:
                    return False

            edges = {}
            for name in names:
                version = assignment[name]
                if version == -1:
                    continue
                row = next(row for row in packages[name] if row["version"] == version)
                active = []
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    other = dep["name"]
                    other_version = assignment[other]
                    if other_version < dep["min"] or other_version > dep["max"]:
                        return False
                    active.append(other)
                edges[name] = active

            reachable = set()
            pending = list(roots)
            while pending:
                name = pending.pop()
                if name in reachable:
                    continue
                version = assignment[name]
                bounds = roots.get(name)
                if version == -1 or (bounds is not None and
                                     not bounds[0] <= version <= bounds[1]):
                    return False
                reachable.add(name)
                pending.extend(edges[name])
            if reachable != {name for name in names if assignment[name] != -1}:
                return False

            finished, active = set(), set()

            def visit(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                if any(not visit(other) for other in edges.get(name, [])):
                    return False
                active.remove(name)
                finished.add(name)
                return True

            return all(visit(name) for name in reachable)

        def search(index):
            if index == len(names):
                return feasible()
            name = names[index]
            for version in domains[name]:
                assignment[name] = version
                if search(index + 1):
                    return True
            assignment.pop(name, None)
            return False

        if not search(0):
            return {"error": "unsatisfiable"}
        return {"versions": {name: assignment[name] for name in names
                              if assignment[name] != -1}}
    return solve


def _build_component_08():
    def solve(data):
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        jobs = [job for job in data["jobs"] if job["id"] not in blocked]
        quotas = data.get("quotas", {})
        best_value = None
        best_ids = None

        for subset in itertools.combinations(jobs, k):
            ids = tuple(sorted(job["id"] for job in subset))
            if not mandatory.issubset(ids):
                continue
            counts = {}
            for job in subset:
                group = job["group"]
                counts[group] = counts.get(group, 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue

            events = []
            for job in subset:
                events.append((job["start"], 1))
                events.append((job["end"], -1))
            active = 0
            valid = True
            for _, delta in sorted(events):
                active += delta
                if active > 2:
                    valid = False
                    break
            if not valid:
                continue

            value = sum(job["value"] for job in subset)
            if (best_value is None or value > best_value or
                    (value == best_value and ids > best_ids)):
                best_value, best_ids = value, ids

        if best_value is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}
    return solve


